content.content:
- The stolen shuriken is not thrown on the step of a volley: the two share one aim, and that aim is led
  (`Jam.Boss.StolenShurikenIsNotLed`).
- The bot needed more than the turn of its circle, and each addition has its test:
  `Jam.Bot.KeepsOffTheWall` (the closer the wall, the more it turns back into the open) and
  `Jam.Bot.KeepsOutOfABlast` (an explosive shuriken counts where it ends: at the wall or at the end of its life).

What the lost fights showed on the way (all 60 lost at first, the hero dead with the boss at 340 to 1460 health):

1. One shuriken per volley was led by accident, through the shared aim. Fixed in the brain.
2. The bot backed into the wall and lost its speed there. Sliding along the wall gave 52 of 60.
3. Almost all the remaining damage was the blast of the explosive shuriken that flew past the bot and went off on
   the wall behind it. No dodge helps there, only room: with it the bot wins every order.

Open: a hero at the wall is punished hard by the stolen shuriken (every third one explodes there). It reads as a
fair rule, "do not let him pin you", but a person has to be able to see it coming: the explosive shuriken needs
its own look in the hands of the boss (block D or the balance ticket T-031).
#include "Game/JamGameMode.h"

#include "Audio/JamMusic.h"
#include "Core/JamConfig.h"
#include "Game/JamPlayerController.h"
#include "Kismet/GameplayStatics.h"
#include "Sim/JamFightSubsystem.h"
#include "UI/JamHUD.h"
#include "View/JamArenaView.h"
#include "View/JamCameraRig.h"
#include "View/JamEffectsView.h"
#include "View/JamFighterView.h"
#include "View/JamProjectilesView.h"

namespace
{
const FLinearColor HeroBeanColor(0.1f, 0.75f, 1.0f);
const FLinearColor BossBeanColor(0.75f, 0.1f, 0.12f);
// The world runs this slow while an Ultimate winds up: presentation only, the simulation counts its own steps.
constexpr float UltimateTimeDilation = 0.3f;

} // namespace

AJamGameMode::AJamGameMode()
{
	PrimaryActorTick.bCanEverTick = true;
	PlayerControllerClass = AJamPlayerController::StaticClass();
	HUDClass = AJamHUD::StaticClass();
	DefaultPawnClass = nullptr;
}

void AJamGameMode::RestartPlayer(AController* NewPlayer)
{
}

void AJamGameMode::StartPlay()
{
	Super::StartPlay();
	Demo.Init();
	LayerSettings = JamConfig::Load<FJamLayerSettings>(JamLayerRules::Section);
	UWorld* World = GetWorld();
	const UJamFightSubsystem* Host = World->GetSubsystem<UJamFightSubsystem>();
	if (!Host)
	{
		return;
	}
	const FJamFight& Fight = Host->GetFight();
	Arena = World->SpawnActor<AJamArenaView>();
	Arena->Init(Host->GetBalance().ArenaRadius);
	HeroView = World->SpawnActor<AJamFighterView>();
	HeroView->Init(Fight.Fighters[EJamSide::Hero].Radius, Fight.Fighters[EJamSide::Hero].Speed, HeroBeanColor);
	BossView = World->SpawnActor<AJamFighterView>();
	BossView->Init(Fight.Fighters[EJamSide::Boss].Radius, Fight.Fighters[EJamSide::Boss].Speed, BossBeanColor);
	Projectiles = World->SpawnActor<AJamProjectilesView>();
	Effects = World->SpawnActor<AJamEffectsView>();
	Effects->Init(Host->GetBalance());
	Rig = World->SpawnActor<AJamCameraRig>();
	Music = World->SpawnActor<AJamMusic>();
}

void AJamGameMode::ReadFightKeys(UJamFightSubsystem& Host, const AJamPlayerController& Player)
{
#if !UE_BUILD_SHIPPING
	if (Player.WasInputKeyJustPressed(EKeys::F5))
	{
		Host.DebugSkip();
	}
	if (Player.WasInputKeyJustPressed(EKeys::F6))
	{
		Host.Restart();
	}
#endif
	// R answers an ending only: a slip of the finger in the middle of the fight costs nothing.
	const EJamPhase Phase = Host.GetFight().Phase;
	if (Player.WasInputKeyJustPressed(EKeys::R) || Player.WasInputKeyJustPressed(EKeys::Enter))
	{
		if (Phase == EJamPhase::HeroDead)
		{
			Host.Retry();
		}
		else if (Phase == EJamPhase::Won)
		{
			Host.Restart();
		}
	}
}

void AJamGameMode::ApplyLayers(const FJamFight& Fight)
{
	const FJamLayers Left = JamLayerRules::For(Fight.Steal.Done, Fight.Phase, LayerSettings);
	HeroView->SetLayers(Left);
	Arena->SetMaterials(Left.bMaterials);
	Effects->bHeroEffects = Left.bEffects;
	Music->SetStems(JamLayerRules::StemsFor(Fight.Steal.Done, Fight.Phase, LayerSettings));
	if (AJamHUD* Hud = Cast<AJamHUD>(GetWorld()->GetFirstPlayerController()->GetHUD()))
	{
		Hud->bBars = Left.bHud;
	}
}

void AJamGameMode::SyncViews(const UJamFightSubsystem& Host, float Time)
{
	const FJamFight& Fight = Host.GetFight();
	const float Alpha = Host.GetAlpha();
	ApplyLayers(Fight);
	for (const FJamEvent& Event : Host.GetFrameEvents())
	{
		if (Event.Type == EJamEvent::Hit)
		{
			(Event.Side == EJamSide::Hero ? HeroView : BossView)->Flash(Time);
		}
	}
	HeroView->Sync(Fight.Fighters[EJamSide::Hero], Alpha, Time);
	BossView->Sync(Fight.Fighters[EJamSide::Boss], Alpha, Time);
	Projectiles->Sync(Fight.Projectiles, Alpha);
	Effects->Sync(Fight, Host.GetFrameEvents(), Alpha, Time);
	Rig->Sync(HeroView->GetActorLocation());
}

void AJamGameMode::Tick(float DeltaSeconds)
{
	Super::Tick(DeltaSeconds);
	UJamFightSubsystem* Host = GetWorld()->GetSubsystem<UJamFightSubsystem>();
	AJamPlayerController* Player = Cast<AJamPlayerController>(GetWorld()->GetFirstPlayerController());
	if (!Host || !Player || !Rig)
	{
		return;
	}
	const FJamFighter& Hero = Host->GetFight().Fighters[EJamSide::Hero];
	if (!bPlayerReady)
	{
		// The controller ticks first, so the keys read here are this frame's keys.
		AddTickPrerequisiteActor(Player);
		Player->SetViewTarget(Rig);
		Player->UseCursor();
		bPlayerReady = true;
	}

	const float Time = GetWorld()->GetTimeSeconds();
	if (Demo.IsOn())
	{
		Host->HeroIntent = Demo.Drive(*Host, Time);
	}
	else
	{
		ReadFightKeys(*Host, *Player);
		Host->HeroIntent = Player->ReadIntent(*Rig, Hero);
	}
	Host->Advance(DeltaSeconds);
	const FJamFight& Now = Host->GetFight();
	const bool bWindingUp = Now.Fighters[EJamSide::Hero].Ultimate.bPending || Now.Fighters[EJamSide::Boss].Ultimate.bPending;
	UGameplayStatics::SetGlobalTimeDilation(this, bWindingUp ? UltimateTimeDilation : 1.f);
	SyncViews(*Host, Time);
	Demo.EndFrame(Time);
}
#pragma once

#include "CoreMinimal.h"
#include "Game/JamDemo.h"
#include "GameFramework/GameModeBase.h"
#include "Sim/JamLayerRules.h"

#include "JamGameMode.generated.h"

class AJamArenaView;
class AJamCameraRig;
class AJamEffectsView;
class AJamFighterView;
class AJamMusic;
class AJamPlayerController;
class AJamProjectilesView;
class UJamFightSubsystem;

/**
 * Conductor of a frame: reads the player's intent, advances the simulation, then places the views and the camera, always
 * in this order. It also builds the scene, since the map is empty.
 */
UCLASS()
class JAMGAME_API AJamGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	AJamGameMode();

	virtual void StartPlay() override;
	virtual void Tick(float DeltaSeconds) override;

	/** The player has no pawn: the hero is a body of the simulation. */
	virtual void RestartPlayer(AController* NewPlayer) override;

private:
	/** The keys that are not part of the fight: the answer to an ending and the debug keys. */
	void ReadFightKeys(UJamFightSubsystem& Host, const AJamPlayerController& Player);

	/** Shows the state of the fight after the frame's steps. */
	void SyncViews(const UJamFightSubsystem& Host, float Time);

	/** Takes the cosmetic layers and the music stems the Publisher has cut, or gives them back. */
	void ApplyLayers(const FJamFight& Fight);

	UPROPERTY()
	TObjectPtr<AJamArenaView> Arena;

	UPROPERTY()
	TObjectPtr<AJamFighterView> HeroView;

	UPROPERTY()
	TObjectPtr<AJamFighterView> BossView;

	UPROPERTY()
	TObjectPtr<AJamProjectilesView> Projectiles;

	UPROPERTY()
	TObjectPtr<AJamEffectsView> Effects;

	UPROPERTY()
	TObjectPtr<AJamCameraRig> Rig;

	UPROPERTY()
	TObjectPtr<AJamMusic> Music;

	/** After which cut each cosmetic layer is gone. */
	FJamLayerSettings LayerSettings;

	/** The bot run that replaces the player's hands when asked for on the command line. */
	FJamDemo Demo;

	/** True once the player controller is wired to the camera. */
	bool bPlayerReady = false;
};

