namespace
{
FJamFeedbackSettings TestFeedback()
{
	FJamFeedbackSettings S;
	S.SlamShake = 20.f;
	S.UltimateShake = 30.f;
	S.ExplosionShake = 10.f;
	S.HeroHurtShake = 8.f;
	S.ShakeSeconds = 0.4f;
	S.ShakeFrequency = 25.f;
	S.SparkPerDamage = 2.f;
	S.SparkMinRadius = 20.f;
	S.SparkMaxRadius = 80.f;
