#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"

#include "JamMusic.generated.h"

class UAudioComponent;

/**
 * The music in layers: four looping stems of the same length start together and stay running, and a cut only fades
 * one of them out. With no stem left the proof-of-concept metronome fades in. How many stems play is decided by
 * JamLayerRules::StemsFor; this actor only fades.
 *
 * The sounds are /Game/Audio/Music/mus_main_<n>_<name> and mus_poc_loop: stubs from Tools/Audio/make_stub_stems.py until
 * Kirill's files replace them under the same names.
 */
UCLASS()
class JAMGAME_API AJamMusic : public AActor
{
	GENERATED_BODY()

public:
	AJamMusic();

	virtual void BeginPlay() override;
	virtual void Tick(float DeltaSeconds) override;

	/** The number of stems that should play, from 0 (the metronome) to all of them. */
	void SetStems(int32 InStems) { Stems = InStems; }

private:
	UAudioComponent* AddTrack(const TCHAR* Name, const TCHAR* Path);

	/** Drums, bass, pad, lead: the order in which they survive the cuts. */
	UPROPERTY()
	TArray<TObjectPtr<UAudioComponent>> Tracks;

	UPROPERTY()
	TObjectPtr<UAudioComponent> Metronome;

	/** Current loudness of each track and of the metronome, last. */
	TArray<float> Volumes;

	int32 Stems = 0;
};
#include "Audio/JamMusic.h"

#include "Components/AudioComponent.h"
#include "Sim/JamLayerRules.h"
#include "Sound/SoundWave.h"
#include "UObject/ConstructorHelpers.h"

namespace
{
// A cut takes a stem away over this time, the stun brings them back as fast: presentation only.
constexpr float FadeSeconds = 0.6f;
constexpr float MusicVolume = 0.8f;

const TCHAR* const StemPaths[] = {
	TEXT("/Game/Audio/Music/mus_main_1_drums.mus_main_1_drums"),
	TEXT("/Game/Audio/Music/mus_main_2_bass.mus_main_2_bass"),
	TEXT("/Game/Audio/Music/mus_main_3_pad.mus_main_3_pad"),
	TEXT("/Game/Audio/Music/mus_main_4_lead.mus_main_4_lead"),
};
const TCHAR* const MetronomePath = TEXT("/Game/Audio/Music/mus_poc_loop.mus_poc_loop");
} // namespace

AJamMusic::AJamMusic()
{
	PrimaryActorTick.bCanEverTick = true;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
	static_assert(UE_ARRAY_COUNT(StemPaths) == JamLayerRules::StemCount, "one sound per stem");
	for (int32 Index = 0; Index < JamLayerRules::StemCount; ++Index)
	{
		Tracks.Add(AddTrack(*FString::Printf(TEXT("Stem%d"), Index + 1), StemPaths[Index]));
	}
	Metronome = AddTrack(TEXT("Metronome"), MetronomePath);
	Stems = JamLayerRules::StemCount;
}

UAudioComponent* AJamMusic::AddTrack(const TCHAR* Name, const TCHAR* Path)
{
	UAudioComponent* Track = CreateDefaultSubobject<UAudioComponent>(Name);
	Track->SetupAttachment(RootComponent);
	Track->bAutoActivate = false;
	Track->bIsUISound = true;
	ConstructorHelpers::FObjectFinder<USoundWave> Finder(Path);
	Track->SetSound(Finder.Object);
	return Track;
}

void AJamMusic::BeginPlay()
{
	Super::BeginPlay();
	Volumes.Init(0.f, Tracks.Num() + 1);
	TArray<UAudioComponent*> All(Tracks);
	All.Add(Metronome);
	for (int32 Index = 0; Index < All.Num(); ++Index)
	{
		if (USoundWave* Wave = Cast<USoundWave>(All[Index]->Sound))
		{
			// Imported as plain sounds: the loop and the silent play are what keeps the stems on one beat.
			Wave->bLooping = true;
			Wave->VirtualizationMode = EVirtualizationMode::PlayWhenSilent;
		}
		Volumes[Index] = Index < Stems || (Index == Tracks.Num() && Stems == 0) ? 1.f : 0.f;
		All[Index]->SetVolumeMultiplier(Volumes[Index] * MusicVolume);
		All[Index]->Play();
	}
}

void AJamMusic::Tick(float DeltaSeconds)
{
	Super::Tick(DeltaSeconds);
	const float Step = DeltaSeconds / FadeSeconds;
	for (int32 Index = 0; Index < Volumes.Num(); ++Index)
	{
		const bool bOn = Index < Tracks.Num() ? Index < Stems : Stems == 0;
		const float Target = bOn ? 1.f : 0.f;
		if (Volumes[Index] == Target)
		{
			continue;
		}
		Volumes[Index] = FMath::Clamp(Volumes[Index] + (bOn ? Step : -Step), 0.f, 1.f);
		UAudioComponent* Track = Index < Tracks.Num() ? Tracks[Index].Get() : Metronome.Get();
		Track->SetVolumeMultiplier(Volumes[Index] * MusicVolume);
	}
}
#!/usr/bin/env bash
# Imports the music stems into /Game/Audio/Music with the engine's ImportAssets commandlet (no open editor needed).
#   import_music.sh [settings.json]     (default Tools/Audio/import_music.json; file paths in it are relative to the root)
# Kirill's stems replace the stubs: put his WAVs under the same names, list them in a settings file, run this again.
set -u
UE="F:/Program Files/Epic Games/UE_5.8"
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd -W)"
SETTINGS="${1:-$ROOT/Tools/Audio/import_music.json}"
LOG="$ROOT/Saved/BuildCycle/import_music.log"
# The commandlet resolves relative file names from the engine's folder: give it a copy with absolute ones.
RESOLVED="$ROOT/Saved/BuildCycle/import_music.resolved.json"
python -c "import json,sys,os; d=json.load(open(sys.argv[1])); [g.__setitem__('Filenames',[os.path.join(sys.argv[2],f).replace(os.sep,'/') for f in g['Filenames']]) for g in d['ImportGroups']]; json.dump(d,open(sys.argv[3],'w'),indent=1)" "$SETTINGS" "$ROOT" "$RESOLVED"
MSYS2_ARG_CONV_EXCL="*" "$UE/Engine/Binaries/Win64/UnrealEditor-Cmd.exe" "$ROOT/JamGame.uproject" -run=ImportAssets \
	-importsettings="$RESOLVED" -nosourcecontrol -unattended -nosplash -abslog="$LOG"
# Exit 1 with "Invalid Destination Path ()" is expected: the commandlet also checks the -dest it was not given.
echo "[import] exit $?"
grep -E "Imported|Error|Warning: .*(Import|Sound)" "$LOG" | cut -c1-200 | head -20
{
	"ImportGroups": [
		{
			"GroupName": "Music",
			"Filenames": [
				"Audio/Stub/mus_main_1_drums.wav",
				"Audio/Stub/mus_main_2_bass.wav",
				"Audio/Stub/mus_main_3_pad.wav",
				"Audio/Stub/mus_main_4_lead.wav",
				"Audio/Stub/mus_poc_loop.wav"
			],
			"DestinationPath": "/Game/Audio/Music",
			"bReplaceExisting": true,
			"bSkipReadOnly": false
		}
	]
}
"""Stub music stems until Kirill's tracks arrive (T-024).

Four looping stems of the same length and tempo, named the way Kirill delivers them, plus the proof-of-concept loop
(a bare metronome) that plays when every stem is cut. Synthesised here from sine, saw and noise: no samples, nothing
third party. 120 BPM, 8 bars, 48 kHz, 16-bit stereo.

    python Tools/Audio/make_stub_stems.py [out_dir]     (default Audio/Stub)
"""

import sys
import wave
from pathlib import Path

import numpy as np

RATE = 48000
BPM = 120
BARS = 8
BEAT = 60.0 / BPM
LENGTH = BARS * 4 * BEAT
N = int(round(LENGTH * RATE))
# Am, F, C, G: two bars each.
ROOTS = [57, 53, 48, 55]
CHORDS = [[57, 60, 64], [53, 57, 60], [48, 52, 55], [55, 59, 62]]
# Lead arpeggio: chord tones by sixteenth, an octave up.
ARP = [0, 1, 2, 1, 2, 0, 1, 2]


def hz(note):
    return 440.0 * 2.0 ** ((note - 69) / 12.0)


def place(track, start, sound):
    """Adds sound at start seconds, wrapping round the end so the loop is seamless."""
    i = int(round(start * RATE)) % N
    end = i + len(sound)
    if end <= N:
        track[i:end] += sound
    else:
        cut = N - i
        track[i:] += sound[:cut]
        track[: end - N] += sound[cut:]


def env(n, attack, decay):
    t = np.arange(n) / RATE
    a = np.clip(t / max(attack, 1e-4), 0, 1)
    return a * np.exp(-t / decay)

