// Lines on the floor: without them a run across a plain floor reads as standing still.
constexpr float GridStep = 250.f;
constexpr float GridWidth = 8.f;
constexpr float GridHeight = 2.f;
const FLinearColor GridColor(0.0f, 0.3f, 0.4f);
// A neon band along the edge of the floor: the arena's end reads at a glance.
constexpr int32 EdgePieces = 64;
