	Neon = InNeon;
	const float Diameter = 2.f * ArenaRadius / JamShapes::UnitSize;
	Floor->SetRelativeScale3D(FVector(Diameter, Diameter, FloorThickness / JamShapes::UnitSize));
	Floor->SetRelativeLocation(FVector(0.0, 0.0, -0.5 * FloorThickness));
	JamShapes::Paint(*Floor, FloorColor);

	for (int32 Index = 0; Index < PostCount; ++Index)
	{
		const float Angle = UE_TWO_PI * Index / PostCount;
		const FVector Location(ArenaRadius * FMath::Cos(Angle), ArenaRadius * FMath::Sin(Angle), 0.5f * PostHeight);
		AddBox(Location, FMath::RadiansToDegrees(Angle), FVector(PostWidth, PostWidth, PostHeight),
			Index % 2 == 0 ? PostColorA : PostColorB, EArenaPiece::Post);
	}
	// Each line is a chord of the floor circle, so the grid ends at the edge.
	for (float Offset = GridStep * FMath::CeilToFloat(-ArenaRadius / GridStep + 0.5f); Offset < ArenaRadius; Offset += GridStep)
	{
		const float Chord = 2.f * FMath::Sqrt(FMath::Square(ArenaRadius) - FMath::Square(Offset));
		AddBox(FVector(0.0, Offset, 0.5 * GridHeight), 0.f, FVector(Chord, GridWidth, GridHeight), GridColor, EArenaPiece::Line);
		AddBox(FVector(Offset, 0.0, 0.5 * GridHeight), 90.f, FVector(Chord, GridWidth, GridHeight), GridColor, EArenaPiece::Line);
	}
	const float EdgeLength = UE_TWO_PI * ArenaRadius / EdgePieces;
	for (int32 Index = 0; Index < EdgePieces; ++Index)
	{
		const float Angle = UE_TWO_PI * (Index + 0.5f) / EdgePieces;
		const FVector Location(ArenaRadius * FMath::Cos(Angle), ArenaRadius * FMath::Sin(Angle), GridHeight);
		AddBox(Location, FMath::RadiansToDegrees(Angle) + 90.f, FVector(EdgeLength, EdgeWidth, GridHeight), EdgeColor, EArenaPiece::Edge);
	}
}

void AJamArenaView::Pulse(float LineGlow)
{
	if (!bMaterials)
	{
		return;
	}
	for (int32 Index = 0; Index < Boxes.Num(); ++Index)
	{
		if (Pieces[Index] == EArenaPiece::Line)
		{
			JamShapes::Glow(*Boxes[Index], BoxColors[Index], LineGlow);
		}
	}
}

float AJamArenaView::GlowOf(EArenaPiece Piece) const
{
	switch (Piece)
	{
		case EArenaPiece::Post:
			return Neon.PostGlow;
		case EArenaPiece::Edge:
			return Neon.EdgeGlow;
		default:
			return Neon.LineGlow;
	}
}

void AJamArenaView::Dress(int32 Index)
{
	UStaticMeshComponent& Box = *Boxes[Index];
	// The grid material draws its own lines: the neon ones would only say the world is still painted.
	Box.SetVisibility(bMaterials || Pieces[Index] == EArenaPiece::Post);
	if (bMaterials)
	{
		JamShapes::Glow(Box, BoxColors[Index], GlowOf(Pieces[Index]));
	}
	else
	{
		JamShapes::Look(Box, BoxColors[Index], true);
	}
}

void AJamArenaView::SetMaterials(bool bOn)
{
	if (bOn == bMaterials)
	{
		return;
	}
	bMaterials = bOn;
	JamShapes::Look(*Floor, FloorColor, !bOn);
	for (int32 Index = 0; Index < Boxes.Num(); ++Index)
	{
		// The grid material draws its own lines: the neon ones would only say the world is still painted.
		Boxes[Index]->SetVisibility(bOn || !BoxIsLine[Index]);
		JamShapes::Look(*Boxes[Index], BoxColors[Index], !bOn);
	}
}

