#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/**
 * Where a fighter aims, whatever the camera is: a cursor ray on the arena plane (top-down) or a look yaw (third and
 * first person). The simulation only ever sees the resulting FJamAim.
 * Tests: Jam.Aim.*
 */
namespace JamAimRules
{
/**
 * Aim at the point where a ray meets the plane Z = PlaneZ. Returns false and leaves InOutAim untouched when the ray never
 * meets the plane. A point on the fighter itself updates Point but keeps the last direction.
 */
JAMGAME_API bool FromRay(const FVector& Origin, const FVector& Dir, float PlaneZ, const FVector2D& From, FJamAim& InOutAim);

/** Aim along a yaw, with the point Reach ahead of the fighter. */
JAMGAME_API FJamAim FromYaw(float YawDeg, const FVector2D& From, float Reach);
} // namespace JamAimRules
#include "Sim/JamAimRules.h"

bool JamAimRules::FromRay(const FVector& Origin, const FVector& Dir, float PlaneZ, const FVector2D& From, FJamAim& InOutAim)
{
	if (FMath::IsNearlyZero(Dir.Z))
	{
		return false;
	}
	const double Distance = (PlaneZ - Origin.Z) / Dir.Z;
	if (Distance <= 0.0)
	{
		return false;
	}
	const FVector Hit = Origin + Dir * Distance;
	InOutAim.Point = FVector2D(Hit.X, Hit.Y);
	const FVector2D ToPoint = InOutAim.Point - From;
	// Closer than a centimetre there is no direction to speak of.
	if (ToPoint.SizeSquared() > 1.0)
	{
		InOutAim.Dir = ToPoint.GetSafeNormal();
	}
	return true;
}

FJamAim JamAimRules::FromYaw(float YawDeg, const FVector2D& From, float Reach)
{
	double Sin = 0.0;
	double Cos = 1.0;
	FMath::SinCos(&Sin, &Cos, FMath::DegreesToRadians(static_cast<double>(YawDeg)));
	FJamAim Aim;
	Aim.Dir = FVector2D(Cos, Sin);
	Aim.Point = From + Aim.Dir * Reach;
	return Aim;
}
