/** The boss stands through his attacks and the pause after them, whatever his intent says. */
bool IsHeld(const FJamFight& Fight, EJamSide Side)
{
	return Side == EJamSide::Boss && JamBossRules::IsBusy(Fight);
}

void MoveFighter(FJamFight& Fight, EJamSide Side, const FJamIntent& Intent, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	Self.PrevPos = Self.Pos;
	if (!Intent.Aim.Dir.IsNearlyZero())
	{
		Self.Facing = Intent.Aim.Dir.GetSafeNormal();
	}
	const bool bHeld = IsHeld(Fight, Side);
	const bool bOwnsDash = JamLoadoutRules::ActionFor(EJamButton::Dash, Side, Fight.Ledger) == EJamAction::Dash;
	if (Intent.bDash && bOwnsDash && !bHeld && JamDashRules::CanStart(Self.Dash, Fight.Tick))
	{
		Self.Dash = JamDashRules::Start(JamDashRules::Direction(Intent.Move, Self.Facing), Fight.Tick, Balance);
		JamFightOps::AddEvent(Fight, EJamEvent::Dash, Side, 0, Self.Pos, 0.f);
	}
	FVector2D Delta = FVector2D::ZeroVector;
	if (JamDashRules::IsDashing(Self.Dash, Fight.Tick))
	{
		// A dash keeps its line: the stick is not read until it ends.
		Delta = Self.Dash.Dir * Self.Dash.StepLength;
	}
	else if (!bHeld)
	{
		Delta = JamMoveRules::Velocity(Intent.Move, Self.Speed) * JamSim::StepDt;
	}
	// A fighter that stands is never nudged, whoever walks into it.
	if (!Delta.IsNearlyZero())
	const FVector2D Along = FVector2D(1.0, 0.0).GetRotated(Event.Amount);
	const FVector2D Middle = Event.Pos + Along * (0.5 * UltimateRange);
	UStaticMeshComponent& Line = Take(JamShapes::Cube(), UltimateColor);
	Line.SetWorldLocationAndRotation(FVector(Middle.X, Middle.Y, UltimateHeight), FRotator(0.0, Event.Amount, 0.0));
	// The line is full width at once and thins out: the cut is the moment, the fade is the afterglow.
	Line.SetWorldScale3D(FVector(UltimateRange, 2.f * UltimateHalfWidth * (1.f - Age), BladeThickness) / JamShapes::UnitSize);
}

void AJamEffectsView::DrawBurst(const FJamEvent& Event, const FJamFight& Fight, float Alpha, float Age)
{
	// A hit on the Publisher is the hero's blow: its spark goes with the hero's other effects.
	const bool bHeroFlourish = (Event.Side == EJamSide::Hero && (Event.Type == EJamEvent::Swing || Event.Type == EJamEvent::Dash)) ||
		(Event.Side == EJamSide::Boss && Event.Type == EJamEvent::Hit);
	if (bHeroFlourish && !bHeroEffects)
	{
		return;
	}
	const FJamFighter& Self = Fight.Fighters[Event.Side];
	const FVector2D SelfPos = FMath::Lerp(Self.PrevPos, Self.Pos, static_cast<double>(Alpha));
	switch (Event.Type)
	{
		case EJamEvent::Swing:
			DrawSwing(Event, Self, SelfPos, Age);
			break;
		case EJamEvent::Explosion:
			DrawDisc(Event.Pos, Event.Amount * FMath::Lerp(ExplosionStartSize, 1.f, Age), FlashHeight, ExplosionColor);
			break;
		case EJamEvent::Slam:
			DrawDisc(Event.Pos, Event.Amount, FlashHeight, SlamColor);
			break;
		case EJamEvent::Dash:
			DrawTrail(Event, Self, SelfPos);
			break;
		case EJamEvent::UltimateSlash:
			DrawSlash(Event, Age);
			break;
		case EJamEvent::Deflected:
			DrawDisc(Event.Pos, DeflectRadius * (1.f - Age), FlashHeight, DeflectColor);
			break;
		case EJamEvent::Hit:
			// Around the body, not under it: a ground flash smaller than the fighter would never be seen.
			DrawDisc(SelfPos, Self.Radius + JamFeedbackRules::SparkRadius(Event.Amount, Feedback) * (1.f - Age), FlashHeight,
				Event.Side == EJamSide::Hero ? HeroSparkColor : BossSparkColor);
			break;
		default:
			break;

