void AJamFighterView::Flash(float Time, float Weight)
{
	// A light hit inside the flash of a heavy one does not dim it.
	const bool bStillFlashing = Time < FlashUntil;
	const float Next = bStillFlashing ? FMath::Max(FlashWeight, Weight) : Weight;
	FlashUntil = Time + FlashSeconds;
	if (Next != FlashWeight)
	{
		FlashWeight = Next;
		// Sync repaints only when the flash starts or ends: a new weight inside one is painted here.
		if (bFlashing)
		{
			Repaint();
		}
	}
}

void AJamFighterView::Animate(float Moving, float Time)
{
	if (!Shown.bAnimation)
	{
		// What a character is before anybody animates it.
		Ronin->SetRelativeLocationAndRotation(FVector::ZeroVector, FRotator::ZeroRotator);
		ShoulderL->SetRelativeRotation(FRotator(0.0, 0.0, -90.0));
		ShoulderR->SetRelativeRotation(FRotator(0.0, 0.0, 90.0));
		return;
	}
	const float Phase = UE_TWO_PI * StepsPerSecond * Time;
	const float Swing = FMath::Sin(Phase) * ArmSwingDegrees * Moving;
	Ronin->SetRelativeLocationAndRotation(
		FVector(0.0, 0.0, FMath::Abs(FMath::Sin(Phase)) * BobInRadii * BodyRadius * Moving), FRotator(-LeanDegrees * Moving, 0.0, 0.0));
	ShoulderL->SetRelativeRotation(FRotator(Swing, 0.0, -IdleArmDegrees));
	ShoulderR->SetRelativeRotation(FRotator(-Swing, 0.0, IdleArmDegrees));
}

void AJamFighterView::Sync(const FJamFighter& Fighter, float Alpha, float Time)
{
	const FVector2D Pos = FMath::Lerp(Fighter.PrevPos, Fighter.Pos, static_cast<double>(Alpha));
	const double Yaw = FMath::RadiansToDegrees(FMath::Atan2(Fighter.Facing.Y, Fighter.Facing.X));
	SetActorLocationAndRotation(FVector(Pos.X, Pos.Y, 0.0), FRotator(0.0, Yaw, 0.0));
	if (Shown.bModel)
	{
		const float StepSpeed = (Fighter.Pos - Fighter.PrevPos).Size() * JamSim::StepsPerSecond;
		Animate(FMath::Clamp(StepSpeed / Speed, 0.f, 1.f), Time);
	}
	const bool bFlashNow = Time < FlashUntil;
	if (bFlashNow != bFlashing)
	{
		bFlashing = bFlashNow;
		Repaint();
	}
}
