FJamIntent AJamPlayerController::ReadIntent(const AJamCameraRig& Rig, const FJamFighter& Hero)
{
	FVector Origin;
	FVector Direction;
	if (DeprojectMousePositionToWorld(Origin, Direction))
	{
		JamAimRules::FromRay(Origin, Direction, 0.f, Hero.Pos, Aim);
	}

	FJamIntent Intent;
	const FVector2D Keys((IsInputKeyDown(EKeys::D) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::A) ? 1.0 : 0.0),
		(IsInputKeyDown(EKeys::W) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::S) ? 1.0 : 0.0));
	Intent.Move = JamMoveRules::WorldMove(Keys, Rig.GetMoveBasisYaw());
	Intent.Aim = Aim;
	Intent.bPrimary = IsInputKeyDown(EKeys::LeftMouseButton);
	Intent.bSecondary = IsInputKeyDown(EKeys::RightMouseButton);
	Intent.bDash = IsInputKeyDown(EKeys::SpaceBar);
	Intent.bParry = IsInputKeyDown(EKeys::Q);
	Intent.bUltimate = IsInputKeyDown(EKeys::E);
	// The steal card is answered with the keys under the left hand: a press, not a hold, so walking left is no answer.
	if (WasInputKeyJustPressed(EKeys::A) || WasInputKeyJustPressed(EKeys::Left))
	{
		Intent.Choice = 0;
	}
	else if (WasInputKeyJustPressed(EKeys::D) || WasInputKeyJustPressed(EKeys::Right))
	{
		Intent.Choice = 1;
	}
	return Intent;
}

