/**
 * A fighter as the player sees it. The same class draws the hero and the boss, only the size and the colour differ.
 *
 * Stand-ins until the art arrives: the full look is a ronin of basic shapes (body, head, hat, two arms, a blade) with a
 * glow and a walk; the last cosmetic layer leaves the bean with a visor. Which layers are left is FJamLayers: the hero
 * loses them to the Publisher's cuts, the boss keeps all of them.
 */
UCLASS()
class JAMGAME_API AJamFighterView : public AActor
{
	GENERATED_BODY()

public:
	AJamFighterView();

	/** Sizes the shapes around a simulation body of this radius. */
	void Init(float Radius, float MaxSpeed, const FLinearColor& Color);

	/** Switches the look to these layers; nothing happens when they did not change. */
	void SetLayers(const FJamLayers& InLayers);

	/** The fighter lost health at Time: the body goes white for a moment, Weight (0 to 1) of the way. */
	void Flash(float Time, float Weight);

	/** Places the view between the last two simulation steps and moves the body. */
	void Sync(const FJamFighter& Fighter, float Alpha, float Time);

private:
	/** Paints every visible part in its colour, white while flashing, or the grid when the materials are gone. */
	void Repaint();

	/** The walk: bob, lean and arm swing by how fast the body moves. Without the animation layer, the T-pose. */
	void Animate(float Moving, float Time);

	UStaticMeshComponent* AddPart(USceneComponent* Parent, const TCHAR* Name, UStaticMesh* Mesh);

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Body;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Visor;

	/** The ronin hangs off this pivot at the feet, so a lean turns the whole figure. */
	UPROPERTY()
	TObjectPtr<USceneComponent> Ronin;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Torso;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Head;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Eyes;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Hat;

	UPROPERTY()
	TObjectPtr<USceneComponent> ShoulderL;

	UPROPERTY()
	TObjectPtr<USceneComponent> ShoulderR;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> ArmL;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> ArmR;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Blade;

	UPROPERTY()
	TObjectPtr<UPointLightComponent> Glow;

	FJamLayers Shown;
	FLinearColor BaseColor = FLinearColor::White;
	float BodyRadius = 0.f;
	float Speed = 1.f;
	float FlashUntil = 0.f;
	float FlashWeight = 1.f;
	bool bFlashing = false;
};

