namespace
{
// Proportions of the bean, in body radii: presentation only.
constexpr float HeightInRadii = 4.5f;
constexpr float VisorHeightAt = 0.78f;
const FVector VisorSizeInRadii(0.5, 1.3, 0.5);
constexpr float VisorForwardInRadii = 0.75f;
const FLinearColor VisorColor(0.02f, 0.02f, 0.03f);

// The stand-in ronin, in body radii: sizes of the shapes and where their centres are, relative to the feet.
const FVector TorsoSize(1.5, 1.3, 2.8);
constexpr float TorsoAt = 1.4f;
constexpr float HeadSize = 1.f;
constexpr float HeadAt = 3.35f;
const FVector EyesSize(0.25, 0.8, 0.18);
const FVector EyesAt(0.42, 0.0, 3.4);
const FVector HatSize(1.8, 1.8, 0.6);
constexpr float HatAt = 3.85f;
const FVector ShoulderAt(0.0, 0.95, 2.55);
const FVector ArmSize(0.38, 0.38, 1.6);
const FVector BladeSize(2.4, 0.12, 0.3);
const FVector BladeAt(1.2, 0.0, -1.55);
const FLinearColor ClothColor(0.03f, 0.03f, 0.05f);
const FLinearColor SkinColor(0.08f, 0.08f, 0.1f);
constexpr float HatShade = 0.45f;
constexpr float BladeWhiteness = 0.6f;

// The walk, at full speed: steps per second, bob height in radii, lean and arm swing in degrees.
constexpr float StepsPerSecond = 2.4f;
constexpr float BobInRadii = 0.18f;
constexpr float LeanDegrees = 12.f;
constexpr float ArmSwingDegrees = 35.f;
// Idle: the arms hang a little away from the body.
constexpr float IdleArmDegrees = 8.f;

// The glow under the fighter: the first thing the hero loses.
constexpr float GlowIntensity = 6000.f;
constexpr float GlowRadiusInRadii = 12.f;
constexpr float GlowHeightInRadii = 2.f;

// How a hit reads on the body: a short white flash.
constexpr float FlashSeconds = 0.09f;
const FLinearColor FlashColor(1.0f, 1.0f, 1.0f);
} // namespace

AJamFighterView::AJamFighterView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));

	Body = AddPart(RootComponent, TEXT("Body"), JamShapes::Sphere());
	Visor = AddPart(RootComponent, TEXT("Visor"), JamShapes::Cube());

	Ronin = CreateDefaultSubobject<USceneComponent>(TEXT("Ronin"));
	Ronin->SetupAttachment(RootComponent);
	Torso = AddPart(Ronin, TEXT("Torso"), JamShapes::Cylinder());
	Head = AddPart(Ronin, TEXT("Head"), JamShapes::Sphere());
	Eyes = AddPart(Ronin, TEXT("Eyes"), JamShapes::Cube());
	Hat = AddPart(Ronin, TEXT("Hat"), JamShapes::Cone());
	ShoulderL = CreateDefaultSubobject<USceneComponent>(TEXT("ShoulderL"));
	ShoulderL->SetupAttachment(Ronin);
	ShoulderR = CreateDefaultSubobject<USceneComponent>(TEXT("ShoulderR"));
	ShoulderR->SetupAttachment(Ronin);
	ArmL = AddPart(ShoulderL, TEXT("ArmL"), JamShapes::Cube());
	ArmR = AddPart(ShoulderR, TEXT("ArmR"), JamShapes::Cube());
	Blade = AddPart(ShoulderR, TEXT("Blade"), JamShapes::Cube());

	Glow = CreateDefaultSubobject<UPointLightComponent>(TEXT("Glow"));
	Glow->SetupAttachment(RootComponent);
	Glow->SetMobility(EComponentMobility::Movable);
	Glow->SetCastShadows(false);
	// The grid is found here, in a constructor: the layers switch to it at runtime.
	JamShapes::Grid();
}

UStaticMeshComponent* AJamFighterView::AddPart(USceneComponent* Parent, const TCHAR* Name, UStaticMesh* Mesh)
{
	UStaticMeshComponent* Part = CreateDefaultSubobject<UStaticMeshComponent>(Name);
	Part->SetupAttachment(Parent);
	JamShapes::Setup(*Part, Mesh);
	return Part;
}

void AJamFighterView::Init(float Radius, float MaxSpeed, const FLinearColor& Color)
{
	const float Height = Radius * HeightInRadii;
	BaseColor = Color;
	BodyRadius = Radius;
	Speed = FMath::Max(1.f, MaxSpeed);
	const float R = Radius / JamShapes::UnitSize;
	Body->SetRelativeScale3D(FVector(2.f * Radius, 2.f * Radius, Height) / JamShapes::UnitSize);
	Body->SetRelativeLocation(FVector(0.0, 0.0, 0.5 * Height));
	Visor->SetRelativeScale3D(VisorSizeInRadii * R);
	Visor->SetRelativeLocation(FVector(Radius * VisorForwardInRadii, 0.0, Height * VisorHeightAt));

	Torso->SetRelativeScale3D(TorsoSize * R);
	Torso->SetRelativeLocation(FVector(0.0, 0.0, TorsoAt * Radius));
	Head->SetRelativeScale3D(FVector(HeadSize * R));
	Head->SetRelativeLocation(FVector(0.0, 0.0, HeadAt * Radius));
	Eyes->SetRelativeScale3D(EyesSize * R);
	Eyes->SetRelativeLocation(EyesAt * Radius);
	Hat->SetRelativeScale3D(HatSize * R);
	Hat->SetRelativeLocation(FVector(0.0, 0.0, HatAt * Radius));
	ShoulderL->SetRelativeLocation(FVector(ShoulderAt.X, -ShoulderAt.Y, ShoulderAt.Z) * Radius);
	ShoulderR->SetRelativeLocation(ShoulderAt * Radius);
	for (UStaticMeshComponent* Arm : { ArmL.Get(), ArmR.Get() })
	{
		Arm->SetRelativeScale3D(ArmSize * R);
		Arm->SetRelativeLocation(FVector(0.0, 0.0, -0.5 * ArmSize.Z * Radius));
	}
	Blade->SetRelativeScale3D(BladeSize * R);
	Blade->SetRelativeLocation(BladeAt * Radius);

	Glow->SetRelativeLocation(FVector(0.0, 0.0, GlowHeightInRadii * Radius));
	Glow->SetIntensity(GlowIntensity);
	Glow->SetAttenuationRadius(GlowRadiusInRadii * Radius);
	Glow->SetLightColor(Color);

	// Forces the first SetLayers to apply everything.
	Shown.bModel = !Shown.bModel;
	SetLayers(FJamLayers());
}

void AJamFighterView::SetLayers(const FJamLayers& InLayers)
{
	if (InLayers == Shown)
	{
		return;
	}
	Shown = InLayers;
	Ronin->SetVisibility(Shown.bModel, true);
	Body->SetVisibility(!Shown.bModel);
	Visor->SetVisibility(!Shown.bModel);
	Glow->SetVisibility(Shown.bEffects);
	Repaint();
}

void AJamFighterView::Repaint()
{
	const bool bGrid = !Shown.bMaterials && !bFlashing;
	const auto Look = [this, bGrid](UStaticMeshComponent& Part, const FLinearColor& Color)
	{ JamShapes::Look(Part, bFlashing ? FMath::Lerp(Color, FlashColor, FlashWeight) : Color, bGrid); };
	if (!Shown.bModel)
	{
		Look(*Body, BaseColor);
		Look(*Visor, VisorColor);
		return;
	}
	Look(*Torso, ClothColor);
	Look(*ArmL, ClothColor);
	Look(*ArmR, ClothColor);
	Look(*Head, SkinColor);
	Look(*Eyes, BaseColor);
	Look(*Hat, BaseColor * HatShade);
	Look(*Blade, FMath::Lerp(BaseColor, FLinearColor::White, BladeWhiteness));
}

void AJamFighterView::Flash(float Time, float Weight)
{
	// A light hit inside the flash of a heavy one does not dim it.
	const bool bStillFlashing = Time < FlashUntil;
	const float Next = bStillFlashing ? FMath::Max(FlashWeight, Weight) : Weight;
	FlashUntil = Time + FlashSeconds;
	if (Next != FlashWeight)
	{
		FlashWeight = Next;
		// Sync repaints only when the flash starts or ends: a new weight inside one is painted here.
		if (bFlashing)
		{
			Repaint();
		}
	}
}

void AJamFighterView::Animate(float Moving, float Time)
{
	if (!Shown.bAnimation)
	{
		// What a character is before anybody animates it.
		Ronin->SetRelativeLocationAndRotation(FVector::ZeroVector, FRotator::ZeroRotator);
		ShoulderL->SetRelativeRotation(FRotator(0.0, 0.0, -90.0));
		ShoulderR->SetRelativeRotation(FRotator(0.0, 0.0, 90.0));
		return;
	}
	const float Phase = UE_TWO_PI * StepsPerSecond * Time;
	const float Swing = FMath::Sin(Phase) * ArmSwingDegrees * Moving;
	Ronin->SetRelativeLocationAndRotation(
		FVector(0.0, 0.0, FMath::Abs(FMath::Sin(Phase)) * BobInRadii * BodyRadius * Moving), FRotator(-LeanDegrees * Moving, 0.0, 0.0));
	ShoulderL->SetRelativeRotation(FRotator(Swing, 0.0, -IdleArmDegrees));
	ShoulderR->SetRelativeRotation(FRotator(-Swing, 0.0, IdleArmDegrees));
}

void AJamFighterView::Sync(const FJamFighter& Fighter, float Alpha, float Time)
{
	const FVector2D Pos = FMath::Lerp(Fighter.PrevPos, Fighter.Pos, static_cast<double>(Alpha));
	const double Yaw = FMath::RadiansToDegrees(FMath::Atan2(Fighter.Facing.Y, Fighter.Facing.X));
	SetActorLocationAndRotation(FVector(Pos.X, Pos.Y, 0.0), FRotator(0.0, Yaw, 0.0));
	if (Shown.bModel)
	{
		const float StepSpeed = (Fighter.Pos - Fighter.PrevPos).Size() * JamSim::StepsPerSecond;
		Animate(FMath::Clamp(StepSpeed / Speed, 0.f, 1.f), Time);
	}
	const bool bFlashNow = Time < FlashUntil;
	if (bFlashNow != bFlashing)
	{
		bFlashing = bFlashNow;
		Repaint();
	}
}

