constexpr float CardOptionRow = 0.16f;
constexpr float CardOptionWidth = 0.2f;
constexpr float CardOptionHeight = 0.14f;
constexpr float CardOptionGap = 0.03f;
constexpr float CardOptionEdge = 4.f;
constexpr float CardPadding = 14.f;
constexpr float CardNameScale = 2.4f;
constexpr float CardNameRow = 0.055f;
constexpr float CardTimerRow = 0.34f;
constexpr float CardTimerHeight = 0.008f;
constexpr float CardHintRow = 0.37f;
constexpr float StunBandTop = 0.14f;
constexpr float StunBandHeight = 0.13f;
const FLinearColor BarBackColor(0.f, 0.f, 0.f, 0.6f);
const FLinearColor BossBarColor(0.9f, 0.15f, 0.15f);
const FLinearColor HeroBarColor(0.2f, 0.9f, 1.0f);
const FLinearColor StolenColor(1.0f, 0.35f, 0.3f);
const FLinearColor EndingBandColor(0.f, 0.f, 0.f, 0.75f);
const FLinearColor WinColor(1.0f, 0.3f, 0.85f);
const FLinearColor LockedColor(0.45f, 0.45f, 0.45f);

/** A button of the hero, the mechanic that lives on it and the name of the key. */
struct FLoadoutRow
{
	EJamButton Button;
	EJamMechanic Mechanic;
	const TCHAR* Key;
};

const FLoadoutRow LoadoutRows[] = {
	{ EJamButton::Primary, EJamMechanic::Katana, TEXT("LMB") },
	{ EJamButton::Secondary, EJamMechanic::Shuriken, TEXT("RMB") },
	{ EJamButton::Dash, EJamMechanic::Dash, TEXT("SPACE") },
	{ EJamButton::Parry, EJamMechanic::Parry, TEXT("Q") },
	{ EJamButton::Ultimate, EJamMechanic::Ultimate, TEXT("E") },
};

/** What stands over an option of the card: the key that gives it away, or the mark of a cut nobody asks about. */
const TCHAR* OptionKey(const FJamStealState& Steal, int32 Index)
{
	if (Steal.bTakesAll)
	{
		return JamTexts::StealAllMark;
	}
	return Index == 0 ? JamTexts::StealLeftKey : JamTexts::StealRightKey;
}
} // namespace

void AJamHUD::DrawBar(float X, float Y, float Width, float Height, float Fraction, const FLinearColor& Color)
{
	if (!bBars)
	{
		return;
	}
	DrawRect(BarBackColor, X, Y, Width, Height);
	DrawRect(Color, X, Y, Width * FMath::Clamp(Fraction, 0.f, 1.f), Height);
}

void AJamHUD::DrawLoadout(const FJamLedger& Ledger, float Meter, float X, float Bottom)
{
	UFont* Font = GEngine->GetMediumFont();
	const int32 RowCount = UE_ARRAY_COUNT(LoadoutRows);
	for (int32 Index = 0; Index < RowCount; ++Index)
	{
		const FLoadoutRow& Row = LoadoutRows[Index];
		const float Y = Bottom - (RowCount - Index) * LoadoutRowHeight;
		const TCHAR* Name = JamLoadoutRules::Name(Row.Mechanic);
		if (Ledger.Has(EJamSide::Hero, Row.Mechanic))
		{
			DrawText(Row.Key, HeroBarColor, X, Y, Font, LoadoutScale);
			const FString Label = Row.Mechanic == EJamMechanic::Ultimate ? JamTexts::UltimateMeter(Name, Meter) : FString(Name);
			DrawText(Label, HeroBarColor, X + LoadoutNameOffset, Y, Font, LoadoutScale);
			continue;
		}
		const bool bBall = JamLoadoutRules::ActionFor(Row.Button, EJamSide::Hero, Ledger) == EJamAction::Ball;
		DrawText(Row.Key, StolenColor, X, Y, Font, LoadoutScale);
		DrawText(JamTexts::LoadoutStolen(bBall, Name), StolenColor, X + LoadoutNameOffset, Y, Font, LoadoutScale);
	}
}

void AJamHUD::DrawHint(const FString& Text, int32 Row)
{
	UFont* Font = GEngine->GetMediumFont();
	float Width = 0.f;
	float Height = 0.f;
	GetTextSize(Text, Width, Height, Font, 1.f);
	DrawText(Text, FLinearColor::White, (1.f - HudMargin) * Canvas->ClipX - Width, HeroBarBottom * Canvas->ClipY - Row * HintRowHeight,
		Font, 1.f);
}

void AJamHUD::DrawCentered(const FString& Text, float Y, float Scale, const FLinearColor& Color)
{
	UFont* Font = GEngine->GetMediumFont();
	float Width = 0.f;
	float Height = 0.f;
	GetTextSize(Text, Width, Height, Font, Scale);
	DrawText(Text, Color, 0.5f * (Canvas->ClipX - Width), Y, Font, Scale);
}

void AJamHUD::DrawStealCard(const FJamFight& Fight)
{
	const FJamStealState& Steal = Fight.Steal;
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	const float Top = CardTop * H;
	UFont* Font = GEngine->GetMediumFont();
	DrawRect(EndingBandColor, 0.f, Top, W, CardHeight * H);
	DrawCentered(Steal.bTakesAll ? JamTexts::StealAllTitle : JamTexts::StealTitle, Top + 0.02f * H, CardTitleScale, StolenColor);
	DrawCentered(Steal.bTakesAll ? JamTexts::StealAllAsk : JamTexts::StealAsk, Top + CardAskRow * H, TextScale, FLinearColor::White);

	// The options stay dim until the card takes an answer: a key held from the fight must not look like a choice.
	const FLinearColor Color = Fight.Tick >= Steal.OpenTick ? HeroBarColor : LockedColor;
	const float OptionWidth = CardOptionWidth * W;
	const float Gap = CardOptionGap * W;
	const int32 Count = Steal.Offer.Num();
	const float Left = 0.5f * (W - Count * OptionWidth - (Count - 1) * Gap);
	const float OptionTop = Top + CardOptionRow * H;
	for (int32 Index = 0; Index < Count; ++Index)
	{
		const float X = Left + Index * (OptionWidth + Gap);
		DrawRect(BarBackColor, X, OptionTop, OptionWidth, CardOptionHeight * H);
		DrawRect(Color, X, OptionTop, OptionWidth, CardOptionEdge);
		DrawText(OptionKey(Steal, Index), Color, X + CardPadding, OptionTop + CardPadding, Font, TextScale);
		DrawText(JamLoadoutRules::Name(Steal.Offer[Index]), Color, X + CardPadding, OptionTop + CardNameRow * H, Font, CardNameScale);
	}

	const float TimerWidth = 2.f * OptionWidth + Gap;
	const float TimeLeft = JamStealRules::TimeLeft(Steal, static_cast<float>(Fight.Tick));
	DrawBar(0.5f * (W - TimerWidth), Top + CardTimerRow * H, TimerWidth, CardTimerHeight * H, TimeLeft, StolenColor);
	DrawCentered(Steal.bTakesAll ? JamTexts::StealAllKey : JamTexts::StealDefault, Top + CardHintRow * H, TextScale, FLinearColor::White);
}

void AJamHUD::DrawStun()
{
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	DrawRect(EndingBandColor, 0.f, StunBandTop * H, W, StunBandHeight * H);
	DrawCentered(JamTexts::StunTitle, (StunBandTop + 0.015f) * H, CardTitleScale, WinColor);
	DrawCentered(JamTexts::StunAsk, (StunBandTop + 0.085f) * H, TextScale, FLinearColor::White);
}

void AJamHUD::DrawEnding(bool bWon)
{
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	DrawRect(EndingBandColor, 0.f, EndingBandTop * H, W, EndingBandHeight * H);
	DrawCentered(bWon ? JamTexts::WinTitle : JamTexts::LossTitle, (EndingBandTop + 0.06f) * H, EndingTitleScale,
		bWon ? WinColor : FLinearColor::White);
	DrawCentered(bWon ? JamTexts::WinHint : JamTexts::LossHint, (EndingBandTop + 0.17f) * H, TextScale, FLinearColor::White);
}

void AJamHUD::DrawPhase(const FJamFight& Fight)
{
	switch (Fight.Phase)
	{
		case EJamPhase::Steal:
			DrawStealCard(Fight);
			break;
		case EJamPhase::Stunned:
			DrawStun();
			break;
		case EJamPhase::HeroDead:
		case EJamPhase::Won:
			DrawEnding(Fight.Phase == EJamPhase::Won);
			break;
		default:
			break;
	}
}

void AJamHUD::DrawHUD()
{
	Super::DrawHUD();
	const UJamFightSubsystem* Host = GetWorld()->GetSubsystem<UJamFightSubsystem>();
	if (!Canvas || !Host)
	{
		return;
	}
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	UFont* Font = GEngine->GetMediumFont();
	const FJamFight& Fight = Host->GetFight();
	const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
	const FJamFighter& Boss = Fight.Fighters[EJamSide::Boss];

	const float BossX = 0.5f * (1.f - BossBarWidth) * W;
	DrawBar(BossX, BossBarTop * H, BossBarWidth * W, BarHeight * H, Boss.Health / FMath::Max(1.f, Boss.MaxHealth), BossBarColor);
	const FString BossText = JamTexts::BossHealth(FMath::CeilToInt32(Boss.Health), FMath::CeilToInt32(Boss.MaxHealth));
	DrawText(BossText, FLinearColor::White, BossX, (BossBarTop + BarHeight) * H + 4.f, Font, TextScale);

	DrawBar(HudMargin * W, HeroBarBottom * H, HeroBarWidth * W, BarHeight * H, Hero.Health / FMath::Max(1.f, Hero.MaxHealth), HeroBarColor);
	const float HeroTextY = HeroBarBottom * H - 28.f;
	DrawText(JamTexts::HeroHealth(FMath::CeilToInt32(Hero.Health)), FLinearColor::White, HudMargin * W, HeroTextY, Font, TextScale);
	DrawLoadout(Fight.Ledger, Hero.Ultimate.Meter, HudMargin * W, HeroTextY - 6.f);

#if !UE_BUILD_SHIPPING
	DrawHint(JamTexts::DebugHint, 0);
#endif
	if (bParryPrompt)
	{
		DrawOverHero(Hero, JamTexts::ParryPrompt, HeroBarColor);
	}
	DrawPhase(Fight);
}

void AJamHUD::DrawOverHero(const FJamFighter& Hero, const FString& Text, const FLinearColor& Color)
{
	// Above the ronin's head, so the call is read where the eyes already are.
	const FVector Screen = Project(FVector(Hero.Pos.X, Hero.Pos.Y, OverHeroHeight));
	UFont* Font = GEngine->GetMediumFont();
	float Width = 0.f;
	float Height = 0.f;
	GetTextSize(Text, Width, Height, Font, OverHeroScale);
	DrawRect(BarBackColor, Screen.X - 0.5f * Width - CardPadding * 0.5f, Screen.Y - Height, Width + CardPadding, Height);
	DrawText(Text, Color, Screen.X - 0.5f * Width, Screen.Y - Height, Font, OverHeroScale);
}

#pragma once

#include "CoreMinimal.h"

/**
 * Every line of text the player reads on the prototype HUD, in one place: the voice of the game is edited here and
 * nowhere else. Names of the mechanics live with the mechanics, in JamLoadoutRules::Name.
 */
namespace JamTexts
{
// The steal card.
inline const TCHAR* const StealTitle = TEXT("THE PUBLISHER HAS NOTES");
inline const TCHAR* const StealAsk = TEXT("Two features are on his desk. Give one away: he will use it against you.");
inline const TCHAR* const StealLeftKey = TEXT("[A]");
inline const TCHAR* const StealRightKey = TEXT("[D]");
inline const TCHAR* const StealDefault = TEXT("No answer: he takes the left one.");
inline const TCHAR* const StealAllTitle = TEXT("FINAL NOTE: CUT THE REST");
inline const TCHAR* const StealAllAsk = TEXT("He takes what you have left. You keep the ball.");
inline const TCHAR* const StealAllMark = TEXT("CUT");
inline const TCHAR* const StealAllKey = TEXT("[A] hand it over");

// The stun before the final blow.
inline const TCHAR* const StunTitle = TEXT("HE IS OUT OF NOTES");
inline const TCHAR* const StunAsk = TEXT("Everything is yours again. E: the Ultimate lands the final blow.");

// The endings.
inline const TCHAR* const WinTitle = TEXT("NEON RONIN: DIRECTOR'S CUT");
inline const TCHAR* const WinHint = TEXT("The Publisher is out of the building.   R: play again");
inline const TCHAR* const LossTitle = TEXT("SHIPPED AS PROOF OF CONCEPT");
inline const TCHAR* const LossHint = TEXT("The Publisher shipped it without you.   R: retry from the last cut");

inline const TCHAR* const DebugHint = TEXT("Debug: F5 skip to the next cut   F6 restart the fight");

inline FString BossHealth(int32 Now, int32 Max)
{
	return FString::Printf(TEXT("THE PUBLISHER  %d / %d"), Now, Max);
}

inline FString HeroHealth(int32 Now)
{
	return FString::Printf(TEXT("RONIN  %d"), Now);
}

/** What a button is left with after a steal: the weak ball on the attack buttons, nothing on the dash. */
inline FString LoadoutStolen(bool bBall, const TCHAR* Mechanic)
{
	return FString::Printf(TEXT("%s    (%s is the Publisher's now)"), bBall ? TEXT("BALL") : TEXT("nothing"), Mechanic);
}
/** The Ultimate's row: how full the meter is, or that it is ready. */
inline FString UltimateMeter(const TCHAR* Mechanic, float Meter)
{
	return Meter >= 1.f ? FString::Printf(TEXT("%s  READY"), Mechanic)
						: FString::Printf(TEXT("%s  %d%%"), Mechanic, FMath::FloorToInt32(Meter * 100.f));
}
} // namespace JamTexts

